    for (const c of org.contacts) {
      const div=document.createElement('div'); div.className='contact';
      const label=document.createElement('p'); label.textContent=`${c.name} ${c.title} / ${c.emails.join('; ')} / ${c.phone || '전화 미제공'}`;div.append(label);
      const b=document.createElement('button');b.type='button';b.textContent='이 담당자 사용';b.onclick=run(()=>{model.contactName=c.name+' '+(c.title==='님'?'':c.title).replace(/님$/,'');model.contactName=model.contactName.trim();model.to=c.emails.join('; ');model.phone=c.phone||'';model.recipient=c.name;model.recipientContact=String(org.contacts.indexOf(c));model.contactManual={...model.contactManual,recipientContact:true};model.recipientConfirmed=false;fillInputs();renderRecipientChoices();save();showOutput('email',emailText(snapshot,model));});div.append(b);area.append(div);
    }
