    const contractKeys=['firm','firmConfirmed','firmNote','krissLead','agreementFile','legalName','partnerRep','partnerLegalAddress','partnerManagement','agreementDate','templateFamily','partnerTel','partnerFax','krissRep','krissLegalAddress','krissTel','krissFax','krissPiDept','krissPiRank','krissPiName','partnerPiDept','partnerPiRank','partnerPiName'];
    root.querySelectorAll('[data-key]').forEach(n=>n.addEventListener('change',()=>{
      const k=n.dataset.key;collect();if(['to','cc','contactName','recipient','phone','postalOrg','address','zip'].includes(k))model.contactManual={...model.contactManual,[k]:true};
      if(k==='sender'){model.senderManual=true;model.senderSource='발신자 직접 입력';$h('#identityNote').textContent=model.senderSource;}
      if(['postalOrg','recipient','address','zip','phone'].includes(k))model.recipientConfirmed=false;
      if(contractKeys.includes(k)){model.agreed=false;model.approved=false;model.sealed=false;$h('#agreementResult').textContent='';$h('#memoResult').textContent='';}
      if(k==='agreed'&&!model.agreed){model.approved=false;model.sealed=false;}if(k==='approved'&&!model.approved)model.sealed=false;
      fillInputs();save();$h('#openPost').hidden=true;
      if(['sender','contactName','firm','firmNote','firmConfirmed'].includes(k))showOutput('email',emailText(snapshot,model));
    }));
    button('mail',()=>{fresh();save();showOutput('email',emailText(snapshot,model));message('메일 초안을 만들었습니다. 첨부할 협약서를 확인해 주세요.');});
