    button('memoCopy',()=>{fresh();collect();copy(memoText(snapshot,model));});button('agreementOriginal',()=>originalFile('agreement'));button('memoOriginal',()=>originalFile('memo'));button('agreementValues',agreementValues);button('agreementHwp',()=>createHwp('agreement'));button('memoHwp',()=>createHwp('memo'));
    button('save',()=>{fresh();save();message('이 건의 작업 내용을 저장했습니다.');});
